// n8n - Code node (JavaScript) - Mode: Run Once for All Items

function onlyDigits(v) {
  return String(v ?? "").replace(/\D/g, "");
}

function toNumber(v) {
  if (v === null || v === undefined) return NaN;
  const s = String(v).trim();
  if (!s) return NaN;
  const n = parseFloat(s.replace(/\./g, "").replace(",", "."));
  return Number.isFinite(n) ? n : NaN;
}

function normStr(v) {
  return String(v ?? "").trim();
}

function getFirstValue(raw) {
  if (Array.isArray(raw)) return raw[0];
  return raw;
}

function normalizeChoice(v) {
  if (v && typeof v === "object") {
    if (typeof v.value === "string") return v.value.trim();
    if (typeof v.label === "string") return v.label.trim();
  }
  return normStr(getFirstValue(v));
}

function normalizeYesNo(v) {
  const s = normalizeChoice(v).toUpperCase();
  if (["SIM", "S", "YES", "Y", "TRUE"].includes(s)) return "SIM";
  if (["NÃO", "NAO", "N", "NO", "FALSE"].includes(s)) return "NAO";
  return "";
}

function formatCurrencyBRL(n) {
  const v = Number(n);
  if (!Number.isFinite(v)) return "R$ 0,00";
  return v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function formatPercent(p) {
  const v = Number(p);
  if (!Number.isFinite(v)) return "0,00%";
  return (v * 100).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + "%";
}

function monthlyRateFromAnnual(taxaAno) {
  const a = Number(taxaAno);
  if (!Number.isFinite(a) || a <= -1) return NaN;
  return Math.pow(1 + a, 1 / 12) - 1;
}

function pickAmortSystem(json) {
  // Prefer campos “normalizados”, mas tenta achar pelo rótulo do formulário também.
  const direct =
    json.sistemaAmortizador ||
    json.sistemaAmortizadorNorm ||
    json.amortizador ||
    json.amortizationSystem;

  let s = normalizeChoice(direct);

  if (!s) {
    // fallback: procura chave que contenha "Sistema amort"
    const key = Object.keys(json).find((k) => k.toLowerCase().includes("sistema amort"));
    if (key) s = normalizeChoice(json[key]);
  }

  s = s.toUpperCase();
  if (s.includes("PRICE")) return "PRICE";
  return "SAC"; // default
}

function calcParcelaPRICE(pv, i, n) {
  // PMT = PV*i / (1 - (1+i)^-n)
  if (!Number.isFinite(pv) || pv <= 0) return NaN;
  if (!Number.isFinite(i) || i < 0) return NaN;
  if (!Number.isFinite(n) || n <= 0) return NaN;

  if (i === 0) return pv / n;
  const denom = 1 - Math.pow(1 + i, -n);
  if (denom <= 0) return NaN;
  return (pv * i) / denom;
}

function calcParcelasSAC(pv, i, n) {
  // Amortização constante: A = PV/n
  // Parcela_t = A + saldo_devedor_anterior * i
  if (!Number.isFinite(pv) || pv <= 0) return { primeira: NaN, ultima: NaN, amort: NaN };
  if (!Number.isFinite(i) || i < 0) return { primeira: NaN, ultima: NaN, amort: NaN };
  if (!Number.isFinite(n) || n <= 0) return { primeira: NaN, ultima: NaN, amort: NaN };

  const amort = pv / n;
  const primeira = amort + pv * i;
  const saldoAntesUltima = pv - amort * (n - 1); // = pv/n
  const ultima = amort + saldoAntesUltima * i;

  return { primeira, ultima, amort };
}

const inputs = $input.all();

return inputs.map(({ json }) => {
  const item = { ...json };

  // ======== ENTRADAS PRINCIPAIS (do seu fluxo) ========
  const bancoLabel = normStr(item.bancoLabel || item.bancoPretendidoLabel || item.bancoPretendido || "");
  const bancoPretendido = normStr(item.bancoPretendido || "");
  const modalidade = normStr(item.modalidade || item.tipoFinanciamento || "");
  const cenario = "RESIDENCIAL"; // pelo seu print, você está usando residencial

  const valorImovel = Number.isFinite(Number(item.valorImovelNumero))
    ? Number(item.valorImovelNumero)
    : toNumber(item.valorImovelNumero ?? item.valorImovel);

  // financiamento informado (seu formulário pede)
  const valorFinanciamentoInformado = Number.isFinite(Number(item.valorFinanciamentoNumero))
    ? Number(item.valorFinanciamentoNumero)
    : toNumber(item.valorFinanciamentoNumero ?? item.valorFinanciamento);

  const rendaBruta = Number.isFinite(Number(item.rendaBrutaFamiliarNumero))
    ? Number(item.rendaBrutaFamiliarNumero)
    : toNumber(item.rendaBrutaFamiliarNumero ?? item.rendaBrutaFamiliar);

  // entrada (recursos próprios) — seu validador já deixa alias valorEntradaNumero
  const entradaRecursosProprios = Number.isFinite(Number(item.valorEntradaNumero))
    ? Number(item.valorEntradaNumero)
    : Number.isFinite(Number(item.valorEntradaRecursoProprioNumero))
      ? Number(item.valorEntradaRecursoProprioNumero)
      : toNumber(item.valorEntradaNumero ?? item.valorEntradaRecursoProprioNumero ?? item.valorEntrada);

  // ======== CORREÇÃO FGTS (AQUI) ========
  const possuiFGTSNorm = item.possuiFGTSNorm || item.possuiFGTS || "";
  const vaiUsarFGTS = normalizeYesNo(possuiFGTSNorm);

  const saldoFGTSNumero = Number.isFinite(Number(item.saldoFGTSNumero))
    ? Number(item.saldoFGTSNumero)
    : Number.isFinite(Number(item.saldoFGTS))
      ? Number(item.saldoFGTS)
      : toNumber(item.saldoFGTSNumero ?? item.saldoFGTS);

  const fgtsConsiderado =
    vaiUsarFGTS === "SIM" && Number.isFinite(saldoFGTSNumero) && saldoFGTSNumero > 0
      ? saldoFGTSNumero
      : 0;

  // entrada total = recursos próprios + FGTS considerado
  const entradaTotalConsiderada =
    (Number.isFinite(entradaRecursosProprios) ? entradaRecursosProprios : 0) + fgtsConsiderado;

  // ======== TAXA (vem do Motor de taxas) ========
  let taxaAno = Number(item.taxaAno);
  let taxaMes = Number(item.taxaMes);

  if (!Number.isFinite(taxaAno)) taxaAno = toNumber(item.taxaAno);
  if (!Number.isFinite(taxaMes)) taxaMes = toNumber(item.taxaMes);

  if (!Number.isFinite(taxaMes) && Number.isFinite(taxaAno)) {
    taxaMes = monthlyRateFromAnnual(taxaAno);
  }

  // ======== PRAZO ========
  const prazoAnos = Number.isFinite(Number(item.prazoAnos)) ? Number(item.prazoAnos) : 30;
  const nParcelas = Number.isFinite(Number(item.nParcelas)) ? Number(item.nParcelas) : prazoAnos * 12;

  // ======== SISTEMA AMORTIZADOR ========
  const sistemaAmortizador = pickAmortSystem(item);

  // ======== VALOR FINANCIADO (estimado) ========
  // Mantém seu comportamento: usa o informado; se vier vazio, tenta 80% do imóvel por padrão.
  let valorFinanciado = Number.isFinite(valorFinanciamentoInformado) && valorFinanciamentoInformado > 0
    ? valorFinanciamentoInformado
    : (Number.isFinite(valorImovel) && valorImovel > 0 ? valorImovel * 0.8 : NaN);

  // ======== PARCELAS ========
  let parcelaPrimeira = NaN;
  let parcelaUltima = NaN;
  let parcelaAproximada = NaN;

  if (sistemaAmortizador === "PRICE") {
    const pmt = calcParcelaPRICE(valorFinanciado, taxaMes, nParcelas);
    parcelaPrimeira = pmt;
    parcelaUltima = pmt;
    parcelaAproximada = pmt;
  } else {
    const sac = calcParcelasSAC(valorFinanciado, taxaMes, nParcelas);
    parcelaPrimeira = sac.primeira;
    parcelaUltima = sac.ultima;
    parcelaAproximada = sac.primeira; // padrão do seu texto: usa a 1ª
  }

  // ======== MÉTRICAS ========
  const ltv = Number.isFinite(valorFinanciado) && Number.isFinite(valorImovel) && valorImovel > 0
    ? (valorFinanciado / valorImovel)
    : null;

  const comprometimentoRendaBruta = Number.isFinite(parcelaPrimeira) && Number.isFinite(rendaBruta) && rendaBruta > 0
    ? (parcelaPrimeira / rendaBruta)
    : null;

  // ======== TEXTO ========
  const bancoShow = bancoLabel || (bancoPretendido ? `Banco ${bancoPretendido}` : "Banco");
  const condicaoTaxa = normStr(item.criterioSelecionado || item.produtoSelecionado || item.condicaoTaxa || "");

  const linhaCondicao = condicaoTaxa ? `\n- Condição de taxa: ${condicaoTaxa}` : "";

  const taxaAnoStr = Number.isFinite(taxaAno) ? formatPercent(taxaAno) : "—";
  const taxaMesStr = Number.isFinite(taxaMes) ? formatPercent(taxaMes) : "—";

  const textoSimulacao =
    `Simulação inicial aproximada feita por IA:\n\n` +
    `- Banco pretendido: ${bancoShow}\n` +
    `- Cenário: ${cenario}\n` +
    `- Modalidade: ${modalidade || "—"}` +
    `${linhaCondicao}\n` +
    `- Valor do imóvel: ${formatCurrencyBRL(valorImovel)}\n` +
    `- Entrada (recursos próprios): ${formatCurrencyBRL(entradaRecursosProprios)}\n` +
    `- FGTS considerado: ${formatCurrencyBRL(fgtsConsiderado)}\n` +
    `- Entrada total considerada: ${formatCurrencyBRL(entradaTotalConsiderada)}\n` +
    `- Valor financiado estimado: ${formatCurrencyBRL(valorFinanciado)}\n` +
    `- Prazo: ${prazoAnos} anos (${nParcelas} meses)\n` +
    `- Taxa de referência: ${taxaAnoStr} a.a (${taxaMesStr} a.m)\n` +
    `- Sistema amortizador: ${sistemaAmortizador} ${sistemaAmortizador === "SAC" ? "(parcela decrescente)" : "(parcela fixa)"}\n` +
    `- Parcela aprox. (1ª): ${formatCurrencyBRL(parcelaPrimeira)}\n` +
    `- Parcela (última): ${formatCurrencyBRL(parcelaUltima)}\n` +
    (Number.isFinite(rendaBruta) ? `- Renda bruta familiar informada: ${formatCurrencyBRL(rendaBruta)}\n` : "") +
    (ltv !== null ? `- LTV (financiamento / imóvel): ${formatPercent(ltv)}\n` : "") +
    (comprometimentoRendaBruta !== null ? `- Comprometimento aprox. da renda bruta: ${formatPercent(comprometimentoRendaBruta)}\n` : "") +
    `\nObservação: Esta é uma simulação para referência. A análise detalhada pode variar conforme política vigente do banco, perfil e validação documental.`;

  // ======== SAÍDA (mantém campos que você já usa) ========
  item.saldoFGTS = Number.isFinite(saldoFGTSNumero) ? saldoFGTSNumero : 0;     // “digitado”
  item.fgtsConsiderado = fgtsConsiderado;                                      // “considerado”
  item.entradaTotalConsiderada = entradaTotalConsiderada;

  item.valorFinanciado = valorFinanciado;

  item.parcelaAproximada = parcelaAproximada;
  item.parcelaPrimeira = parcelaPrimeira;
  item.parcelaUltima = parcelaUltima;

  item.ltv = ltv;
  item.comprometimentoRendaBruta = comprometimentoRendaBruta;

  item.sistemaAmortizador = sistemaAmortizador;
  item.textoSimulacao = textoSimulacao;

  return { json: item };
});

const item = $json;
const errors = [];

/* =========================
   HELPERS
========================= */

function onlyDigits(v) {
  return String(v ?? "").replace(/\D/g, "");
}

function toNumber(v) {
  if (v === null || v === undefined) return NaN;
  const s = String(v).trim();
  if (!s) return NaN;

  const n = parseFloat(s.replace(/\./g, "").replace(",", "."));
  return Number.isFinite(n) ? n : NaN;
}

function getFirstValue(raw) {
  if (Array.isArray(raw)) return raw[0];
  return raw;
}

function normalizeText(v) {
  return String(v ?? "").trim();
}

function normalizeChoice(v) {
  if (v && typeof v === "object") {
    if (typeof v.value === "string") return v.value.trim();
    if (typeof v.label === "string") return v.label.trim();
  }
  return normalizeText(getFirstValue(v));
}

function normalizeYesNo(v) {
  const s = normalizeChoice(v).toUpperCase();
  if (["SIM", "S", "YES", "Y", "TRUE"].includes(s)) return "SIM";
  if (["NÃO", "NAO", "N", "NO", "FALSE"].includes(s)) return "NAO";
  return "";
}

// dd/mm/aaaa ou yyyy-mm-dd
function parseDateAny(v) {
  const s = normalizeText(v);
  if (!s) return null;

  if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) {
    const [dd, mm, yyyy] = s.split("/").map(Number);
    const d = new Date(yyyy, mm - 1, dd);
    return Number.isFinite(d.getTime()) ? d : null;
  }

  const d = new Date(s);
  return Number.isFinite(d.getTime()) ? d : null;
}

function calcAge(birthDate) {
  if (!birthDate) return null;
  const today = new Date();
  let age = today.getFullYear() - birthDate.getFullYear();
  const m = today.getMonth() - birthDate.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) age--;
  return age >= 0 && age <= 120 ? age : null;
}

/* =========================
   RÓTULOS DO FORMULÁRIO
========================= */

const FIELDS = {
  nomeCompleto: "Digite seu nome completo",
  cpf: "Digite seu CPF",

  // ✅ atualizado conforme sua nova pergunta
  celular: "Digite seu número de celular, DDD + Número. Ex: 11 9...",

  email:
    "Digite seu e-mail (em caso de falhas, um e-mail será enviado solicitando o preenchimento do formulário com os dados corretos).",

  valorFinanciamento: "Digite o valor do financiamento",
  modalidade: "Qual o tipo de financiamento você pretende fazer?",
  valorImovel: "Digite o valor do imóvel",
  rendaBrutaFamiliar: "Qual a renda bruta familiar de todos os participantes?",

  possuiFGTS: "Possui FGTS?",
  saldoFGTS: "Qual o valor aproximado do saldo do FGTS em caso de utilização?",

  pretendeEntradaRecursoProprio: "Pretende dar algum valor de entrada (recurso próprio)?",
  valorEntradaRecursoProprio: "Se sim, qual valor você pretende dar de entrada",

  bancoPretendido: "Qual banco você pretende realizar seu financiamento?",
  uf: "Digite seu estado",

  dataNascimentoMaiorIdade: "Qual a data de nascimento do proponente de maior idade?",

  consentimentoLGPD:
    "Termo de consentimento. Declaro que li e concordo com o uso dos meus dados pessoais para realização de simulações de crédito imobiliário, contato pela GoodCredit e registro das informações necessárias, em conformidade com a LGPD.",
};

/* =========================
   LEITURA
========================= */

const nomeCompleto = normalizeText(item[FIELDS.nomeCompleto]);
const cpfBruto = item[FIELDS.cpf];

// ✅ leitura robusta do celular: tenta pelo novo rótulo, mas aceita o antigo também (para evitar falhas em testes antigos)
const celularBruto =
  item[FIELDS.celular] ??
  item["Digite seu número de celular"] ??
  item["Digite seu número de celular (com DDD)"] ??
  item["Whatsapp para resposta (com DDD)"] ??
  item["WhatsApp para resposta (com DDD)"] ??
  item["WhatsApp para resposta"] ??
  item["Whatsapp para resposta"] ??
  item["Celular"] ??
  item["Telefone"] ??
  "";

const emailRaw = item[FIELDS.email] ?? "";

const valorFinStr = item[FIELDS.valorFinanciamento];
const modalidade = normalizeChoice(item[FIELDS.modalidade]);

const valorImovelStr = item[FIELDS.valorImovel];
const rendaBrutaStr = item[FIELDS.rendaBrutaFamiliar];

const possuiFGTS = normalizeYesNo(item[FIELDS.possuiFGTS]);
const saldoFGTSStr = item[FIELDS.saldoFGTS];

const pretendeEntradaRP = normalizeYesNo(item[FIELDS.pretendeEntradaRecursoProprio]);
const valorEntradaRPStr = item[FIELDS.valorEntradaRecursoProprio];

const bancoPretendido = normalizeChoice(item[FIELDS.bancoPretendido]);

const ufBruto = normalizeText(item[FIELDS.uf]);
const consentLGPD = normalizeYesNo(item[FIELDS.consentimentoLGPD]);

const nascimentoMaiorIdadeRaw = normalizeText(item[FIELDS.dataNascimentoMaiorIdade]);

/* =========================
   NOME
========================= */
if (!nomeCompleto || nomeCompleto.length < 5 || !nomeCompleto.includes(" ")) {
  errors.push("Nome completo inválido. Informe nome e sobrenome.");
}

/* =========================
   CPF
========================= */
const cpf = onlyDigits(cpfBruto);

function isValidCPF(c) {
  if (!c || c.length !== 11 || /^(\d)\1+$/.test(c)) return false;

  let soma = 0;
  for (let i = 0; i < 9; i++) soma += parseInt(c.charAt(i), 10) * (10 - i);
  let resto = (soma * 10) % 11;
  if (resto === 10) resto = 0;
  if (resto !== parseInt(c.charAt(9), 10)) return false;

  soma = 0;
  for (let i = 0; i < 10; i++) soma += parseInt(c.charAt(i), 10) * (11 - i);
  resto = (soma * 10) % 11;
  if (resto === 10) resto = 0;

  return resto === parseInt(c.charAt(10), 10);
}

if (cpf.length !== 11 || !isValidCPF(cpf)) {
  errors.push("CPF inválido.");
}

/* =========================
   CELULAR (DDD + 9 dígitos)
========================= */
const celularSomenteDigitos = onlyDigits(celularBruto || "");
if (!/^\d{11}$/.test(celularSomenteDigitos)) {
  errors.push(`Telefone celular inválido. Informe DDD + 9 dígitos (11 dígitos).`);
} else {
  const dddNum = Number(celularSomenteDigitos.slice(0, 2));
  const terceiroDigito = celularSomenteDigitos.charAt(2);
  if (!Number.isInteger(dddNum) || dddNum < 11 || dddNum > 99) errors.push("DDD do celular inválido.");
  if (terceiroDigito !== "9") errors.push("Número de celular inválido. Use DDD + 9xxxxxxxx.");
  if (/^(\d)\1{10}$/.test(celularSomenteDigitos)) errors.push("Telefone celular inválido (sequência repetida).");
}
item.celularLimpo = celularSomenteDigitos;

/* =========================
   E-MAIL
========================= */
const emailStr = normalizeText(emailRaw);
if (!emailStr) {
  errors.push("E-mail não informado.");
} else {
  const regexEmailBoa =
    /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9-]+(\.[a-z0-9-]+)+$/i;
  if (!regexEmailBoa.test(emailStr)) errors.push("E-mail em formato inválido.");
}

/* =========================
   NÚMEROS
========================= */
const valorImovel = toNumber(valorImovelStr);
const valorFinanciamento = toNumber(valorFinStr);
const rendaBrutaFamiliar = toNumber(rendaBrutaStr);

if (!Number.isFinite(valorImovel) || valorImovel <= 0) errors.push("Valor do imóvel inválido ou não informado.");
if (!Number.isFinite(valorFinanciamento) || valorFinanciamento <= 0) errors.push("Valor do financiamento inválido ou não informado.");
if (!Number.isFinite(rendaBrutaFamiliar) || rendaBrutaFamiliar <= 0) errors.push("Renda bruta familiar inválida ou não informada.");
if (Number.isFinite(valorImovel) && Number.isFinite(valorFinanciamento) && valorFinanciamento > valorImovel) {
  errors.push("Valor do financiamento maior que o valor do imóvel.");
}

/* =========================
   MODALIDADE
========================= */
if (!modalidade || modalidade.toLowerCase().includes("select")) {
  errors.push("Selecione o tipo de financiamento (Novo/Usado/Terreno).");
}

/* =========================
   FGTS
========================= */
if (!possuiFGTS) errors.push("Informe se possui FGTS (Sim ou Não).");
const saldoFGTS = toNumber(saldoFGTSStr);
const saldoFGTSFinal = (possuiFGTS === "SIM" && Number.isFinite(saldoFGTS) && saldoFGTS >= 0) ? saldoFGTS : 0;

/* =========================
   ENTRADA (RECURSO PRÓPRIO)
========================= */
if (!pretendeEntradaRP) errors.push("Informe se pretende dar entrada com recurso próprio (Sim ou Não).");

const valorEntradaRecursoProprio = toNumber(valorEntradaRPStr);
let valorEntradaRecursoProprioFinal = 0;

if (pretendeEntradaRP === "SIM") {
  if (!Number.isFinite(valorEntradaRecursoProprio) || valorEntradaRecursoProprio <= 0) {
    errors.push("Informe o valor de entrada (recurso próprio).");
  } else {
    valorEntradaRecursoProprioFinal = valorEntradaRecursoProprio;
  }
} else if (pretendeEntradaRP === "NAO") {
  valorEntradaRecursoProprioFinal = 0;
}

if (Number.isFinite(valorImovel) && valorEntradaRecursoProprioFinal > valorImovel) {
  errors.push("Valor de entrada (recurso próprio) maior que o valor do imóvel.");
}

/* =========================
   BANCO
========================= */
if (!bancoPretendido) errors.push("Selecione o banco pretendido.");

/* =========================
   UF (aceita sigla e nome)
========================= */
const ufsValidas = new Set([
  "AC","AL","AP","AM","BA","CE","DF","ES","GO","MA",
  "MT","MS","MG","PA","PB","PR","PE","PI","RJ","RN",
  "RS","RO","RR","SC","SP","SE","TO"
]);

function normalizeUF(s) {
  const raw = normalizeText(s).toUpperCase();

  if (ufsValidas.has(raw)) return raw;

  const noAccents = raw.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const map = {
    "ACRE": "AC",
    "ALAGOAS": "AL",
    "AMAPA": "AP",
    "AMAZONAS": "AM",
    "BAHIA": "BA",
    "CEARA": "CE",
    "DISTRITO FEDERAL": "DF",
    "ESPIRITO SANTO": "ES",
    "GOIAS": "GO",
    "MARANHAO": "MA",
    "MATO GROSSO": "MT",
    "MATO GROSSO DO SUL": "MS",
    "MINAS GERAIS": "MG",
    "PARA": "PA",
    "PARAIBA": "PB",
    "PARANA": "PR",
    "PERNAMBUCO": "PE",
    "PIAUI": "PI",
    "RIO DE JANEIRO": "RJ",
    "RIO GRANDE DO NORTE": "RN",
    "RIO GRANDE DO SUL": "RS",
    "RONDONIA": "RO",
    "RORAIMA": "RR",
    "SANTA CATARINA": "SC",
    "SAO PAULO": "SP",
    "SERGIPE": "SE",
    "TOCANTINS": "TO",
  };

  return map[noAccents] || "";
}

const uf = normalizeUF(ufBruto);
if (!uf) errors.push("UF inválida. Informe a sigla (SP) ou o nome (São Paulo).");

/* =========================
   DATA NASCIMENTO (MAIOR IDADE)
========================= */
const nascimentoMaiorIdade = parseDateAny(nascimentoMaiorIdadeRaw);
const idadeMaiorProponente = calcAge(nascimentoMaiorIdade);

if (!nascimentoMaiorIdade) {
  errors.push("Data de nascimento do proponente mais velho inválida ou não informada.");
} else {
  const hoje = new Date();
  if (nascimentoMaiorIdade > hoje) errors.push("Data de nascimento não pode ser futura.");
  if (idadeMaiorProponente !== null && idadeMaiorProponente < 18) errors.push("Proponente mais velho deve ter 18+ anos.");
}

/* =========================
   CONSENTIMENTO LGPD
========================= */
if (consentLGPD !== "SIM") errors.push("É necessário aceitar o termo de consentimento (LGPD) para prosseguir.");

/* =========================
   SAÍDA
========================= */
item.valid = errors.length === 0;
item.validationErrors = errors;

item.nomeCompletoNormalizado = nomeCompleto;
item.cpfLimpo = cpf;
item.emailValidado = emailStr;
item.uf = uf;

item.valorImovelNumero = valorImovel;
item.valorFinanciamentoNumero = valorFinanciamento;
item.rendaBrutaFamiliarNumero = rendaBrutaFamiliar;

item.possuiFGTSNorm = possuiFGTS;
item.saldoFGTSNumero = saldoFGTSFinal;

item.entradaRecursoProprioNorm = pretendeEntradaRP;
item.valorEntradaRecursoProprioNumero = valorEntradaRecursoProprioFinal;

// alias compatível com nós antigos
